"""Certified real feasibility for rational polynomial equality systems.

The positive-dimensional backend follows the critical/polar reduction of
Aubry, Rouillier and Safey El Din. Certified equidimensional pieces are
reduced recursively to zero-dimensional systems; the RUR solver then constructs exact real
witnesses. Generic polar parameters are handled symbolically over a rational
function field, with an exact exceptional hypersurface controlling specialization.

Algorithmic reference: Aubry--Rouillier--Safey El Din (2002), [ARS2002] in
``docs/references.md``.  The implementation adds semialg-specific exact
generic-specialization and certificate checks.
"""

from __future__ import annotations

from collections.abc import Iterable, Sequence
from dataclasses import dataclass
from itertools import combinations

import sympy as sp

from ._zero_testing import certified_zero
from .algebraic.equality_ideal import EqualityIdealContext, _monomial_ideal_dimension
from .algebraic.groebner_utils import lex_basis_generators
from .algebraic.rational_univariate import RationalUnivariateError
from .algebraic_decomposition import equidimensional_decomposition, verify_decomposition_certificate
from .solve.zero_dimensional import solve_zero_dimensional_system


@dataclass(frozen=True)
class RealAlgebraicFeasibilityResult:
    variables: tuple[sp.Symbol, ...]
    satisfiable: bool | None
    witness: tuple[tuple[sp.Symbol, sp.Expr], ...] | None
    complete: bool
    method: str
    zero_dimensional_systems: tuple[tuple[sp.Expr, ...], ...] = ()
    notes: tuple[str, ...] = ()

    @property
    def assignment(self) -> dict[sp.Symbol, sp.Expr] | None:
        return dict(self.witness) if self.witness is not None else None

    def require_decision(self) -> bool:
        if not self.complete or self.satisfiable is None:
            raise NotImplementedError("real-algebraic feasibility certification is incomplete")
        return self.satisfiable


def _normalize(
    equations: Iterable[sp.Expr | sp.Equality], variables: tuple[sp.Symbol, ...]
) -> tuple[sp.Expr, ...]:
    out: list[sp.Expr] = []
    for equation in equations:
        expr = sp.sympify(equation)
        if isinstance(expr, sp.Equality):
            expr = expr.lhs - expr.rhs
        expr = sp.expand(expr)
        if expr != 0:
            sp.Poly(expr, *variables, domain=sp.QQ)
            out.append(expr)
    return tuple(out)


def _extract_triangular(
    basis: Sequence[sp.Expr], variables: tuple[sp.Symbol, ...]
) -> tuple[tuple[sp.Expr, ...], tuple[sp.Symbol, ...], tuple[sp.Symbol, ...]]:
    remaining = list(basis)
    triangular: list[sp.Expr] = []
    high: list[sp.Symbol] = []
    low: list[sp.Symbol] = []
    for variable in reversed(variables):
        active = [poly for poly in remaining if poly.has(variable)]
        remaining = [poly for poly in remaining if not poly.has(variable)]
        if active:
            chosen = min(active, key=lambda poly: int(sp.degree(poly, variable)))
            high.append(variable)
            triangular.append(chosen)
        else:
            low.append(variable)
    return tuple(reversed(triangular)), tuple(reversed(high)), tuple(reversed(low))


def _gamma_a(
    triangular: Sequence[sp.Expr],
    point: Sequence[int],
    high: Sequence[sp.Symbol],
    low: Sequence[sp.Symbol],
) -> tuple[sp.Expr, ...]:
    codim = len(high)
    if codim == 0 or not triangular:
        return tuple()
    t = tuple(triangular)
    high_matrix = sp.Matrix([[sp.diff(poly, x) for x in high] for poly in t])
    augmented_high = high_matrix.col_join(
        sp.Matrix([[x - a for x, a in zip(high, point[-codim:], strict=True)]])
    )
    minors = []
    for rows in combinations(range(augmented_high.rows), codim):
        minors.append(sp.expand(augmented_high.extract(rows, range(codim)).det()))
    minors = list(reversed(minors))
    low_matrix = sp.Matrix([[sp.diff(poly, x) for x in low] for poly in t])
    augmented_low = low_matrix.col_join(
        sp.Matrix([[x - a for x, a in zip(low, point[:-codim], strict=True)]])
    )
    signs = tuple((-1) ** i for i in range(codim + 1))
    gamma: list[sp.Expr] = []
    for column in range(augmented_low.cols):
        values = [augmented_low[row, column] for row in range(augmented_low.rows)]
        if len(values) != len(minors):
            continue
        gamma.append(
            sp.expand(
                sum(
                    s * value * minor for s, value, minor in zip(signs, values, minors, strict=True)
                )
            )
        )
    return tuple(g for g in gamma if g != 0)


def _solve_real_zero_dimensional(
    system: Sequence[sp.Expr],
    variables: tuple[sp.Symbol, ...],
    *,
    solver=solve_zero_dimensional_system,
) -> tuple[tuple[tuple[sp.Expr, ...], ...] | None, str | None]:
    """Run the exact zero-dimensional backend with explicit incomplete semantics."""
    try:
        points = solver(system, variables=variables, real=True)
    except RationalUnivariateError:
        return None, "rur_failure"
    return tuple(points), None


def _groebner_dimension_over_fraction_field(
    generators: Sequence[sp.Expr],
    variables: tuple[sp.Symbol, ...],
    parameters: tuple[sp.Symbol, ...],
) -> tuple[int, sp.polys.polytools.GroebnerBasis]:
    """Return generic fiber dimension over QQ(parameters) and its lex basis."""
    domain = sp.QQ.frac_field(*parameters)
    basis = sp.groebner(generators, *variables, order="grevlex", domain=domain)
    if any(poly.as_expr() == 1 for poly in basis.polys):
        return -1, basis
    leading_exponents = tuple(
        tuple(int(e) for e in poly.LM(order=basis.order).exponents) for poly in basis.polys
    )
    return _monomial_ideal_dimension(leading_exponents, len(variables)), basis


def _specialization_guard(
    basis: sp.polys.polytools.GroebnerBasis, parameters: tuple[sp.Symbol, ...]
) -> sp.Expr:
    """Polynomial whose nonvanishing preserves the computed generic Groebner basis."""
    guard = sp.Integer(1)
    for poly in basis.polys:
        for coeff in poly.coeffs():
            _num, den = sp.fraction(sp.cancel(sp.sympify(coeff)))
            guard = sp.expand(guard * den)
    if guard == 0:
        raise RationalUnivariateError("symbolic polar specialization produced a zero guard")
    return sp.primitive(sp.Poly(guard, *parameters, domain=sp.QQ))[1].as_expr()


def _rational_point_off_hypersurface(
    polynomial: sp.Expr, parameters: tuple[sp.Symbol, ...]
) -> tuple[sp.Integer, ...]:
    """Construct exactly a nonnegative integer point where ``polynomial`` is nonzero.

    At each stage a nonzero univariate specialization has only finitely many
    integer roots, so the inner search is provably terminating; there is no
    bounded genericity heuristic.
    """
    current = sp.Poly(polynomial, *parameters, domain=sp.QQ)
    if current.is_zero:
        raise RationalUnivariateError("bad-parameter guard vanished identically")
    assignments: dict[sp.Symbol, sp.Integer] = {}
    for i, parameter in enumerate(parameters):
        remaining = parameters[i + 1 :]
        value = 0
        while True:
            candidate_expr = sp.expand(current.as_expr().subs(parameter, value))
            if remaining:
                candidate = sp.Poly(candidate_expr, *remaining, domain=sp.QQ)
                nonzero = not candidate.is_zero
            else:
                candidate = sp.sympify(candidate_expr)
                nonzero = candidate != 0
            if nonzero:
                assignments[parameter] = sp.Integer(value)
                current = candidate
                break
            value += 1
    return tuple(assignments[p] for p in parameters)


def _exact_generic_polar_specialization(
    equations: tuple[sp.Expr, ...],
    triangular: tuple[sp.Expr, ...],
    high: tuple[sp.Symbol, ...],
    low: tuple[sp.Symbol, ...],
    variables: tuple[sp.Symbol, ...],
    current_dim: int,
) -> tuple[tuple[sp.Expr, ...] | None, tuple[str, ...]]:
    """Build a generic polar over QQ(a), characterize bad parameters, specialize exactly."""
    parameters = tuple(sp.Dummy(f"ars_a{i}") for i in range(len(variables)))
    gamma = _gamma_a(triangular, parameters, high, low)
    if not gamma:
        return None, ("symbolic_polar_empty",)
    try:
        generic_dim, generic_basis = _groebner_dimension_over_fraction_field(
            (*equations, *gamma), variables, parameters
        )
    except (sp.PolynomialError, ValueError, TypeError, NotImplementedError) as exc:
        return None, (f"symbolic_polar_elimination_failure:{type(exc).__name__}",)
    if generic_dim < 0:
        return None, ("generic_polar_empty",)
    if generic_dim >= current_dim:
        return None, (f"generic_polar_no_dimension_drop:{current_dim}->{generic_dim}",)
    try:
        guard = _specialization_guard(generic_basis, parameters)
        point = _rational_point_off_hypersurface(guard, parameters)
    except (sp.PolynomialError, RationalUnivariateError, ValueError, TypeError) as exc:
        return None, (f"bad_parameter_characterization_failure:{type(exc).__name__}",)
    specialized_gamma = tuple(
        sp.expand(g.subs(dict(zip(parameters, point, strict=True)))) for g in gamma
    )
    candidate = EqualityIdealContext.build((*equations, *specialized_gamma), variables)
    # Independently verify the promised generic dimension after specialization.
    if candidate.inconsistent or candidate.dimension != generic_dim:
        return None, ("generic_specialization_verification_failed",)
    guard_degree = int(sp.Poly(guard, *parameters, domain=sp.QQ).total_degree())
    return tuple(candidate.generators), (
        f"symbolic_generic_polar_dimension_drop:{current_dim}->{generic_dim}",
        f"bad_parameter_guard_degree:{guard_degree}",
        "exact_generic_specialization",
    )


def _polar_zero_dimensional_systems(
    equations: tuple[sp.Expr, ...],
    variables: tuple[sp.Symbol, ...],
    *,
    max_generic_attempts: int,
    max_pieces: int,
    depth: int = 0,
) -> tuple[tuple[tuple[sp.Expr, ...], ...], bool, tuple[str, ...]]:
    if depth > len(variables) + 2:
        return tuple(), False, ("polar_recursion_limit",)
    context = EqualityIdealContext.build(equations, variables)
    if context.inconsistent:
        return tuple(), True, tuple()
    if context.zero_dimensional:
        return (tuple(context.generators),), True, tuple()

    decomposition = equidimensional_decomposition(equations, variables, max_pieces=max_pieces)
    if (
        not decomposition.complete
        or decomposition.certificate is None
        or not verify_decomposition_certificate(decomposition.certificate)
    ):
        return tuple(), False, ("uncertified_equidimensional_decomposition",)

    terminals: list[tuple[sp.Expr, ...]] = []
    notes: list[str] = []
    for piece in decomposition.pieces:
        piece_context = EqualityIdealContext.build(piece.equations, variables)
        if piece_context.zero_dimensional:
            terminals.append(tuple(piece_context.generators))
            continue
        basis = lex_basis_generators(piece_context.generators, variables, domain=sp.QQ)
        triangular, high, low = _extract_triangular(basis, variables)
        if not high:
            return tuple(terminals), False, (*notes, "triangular_extraction_failed")
        current_dim = piece_context.dimension
        reduced, generic_notes = _exact_generic_polar_specialization(
            tuple(piece_context.generators), triangular, high, low, variables, current_dim
        )
        notes.extend(generic_notes)
        if reduced is None:
            return tuple(terminals), False, tuple(notes)
        sub, complete, subnotes = _polar_zero_dimensional_systems(
            reduced,
            variables,
            max_generic_attempts=max_generic_attempts,
            max_pieces=max_pieces,
            depth=depth + 1,
        )
        terminals.extend(sub)
        notes.extend(subnotes)
        if not complete:
            return tuple(terminals), False, tuple(notes)
    return tuple(terminals), True, tuple(notes)


def _real_algebraic_feasibility_result(
    equations: Iterable[sp.Expr | sp.Equality],
    variables: Sequence[sp.Symbol],
    *,
    max_generic_attempts: int = 64,
    max_pieces: int = 128,
) -> RealAlgebraicFeasibilityResult:
    """Decide real feasibility of rational polynomial equations when ARS certifies it."""
    vars_ = tuple(variables)
    if not vars_:
        raise ValueError("a nonempty variable list is required")
    if max_generic_attempts < 1:
        raise ValueError("max_generic_attempts must be positive")
    if max_pieces < 1:
        raise ValueError("max_pieces must be positive")
    try:
        eqs = _normalize(equations, vars_)
    except (sp.PolynomialError, ValueError, TypeError) as exc:
        raise RationalUnivariateError(
            "ARS feasibility requires rational polynomial equations"
        ) from exc
    if not eqs:
        witness = tuple((v, sp.Integer(0)) for v in vars_)
        return RealAlgebraicFeasibilityResult(
            vars_, True, witness, True, "ars", notes=("empty_equality_system",)
        )
    context = EqualityIdealContext.build(eqs, vars_)
    if context.inconsistent:
        return RealAlgebraicFeasibilityResult(
            vars_, False, None, True, "ars", notes=("unit_ideal",)
        )
    if context.zero_dimensional:
        systems = (tuple(context.generators),)
        points, failure = _solve_real_zero_dimensional(eqs, vars_)
        if failure is not None or points is None:
            return RealAlgebraicFeasibilityResult(
                vars_, None, None, False, "ars", systems, ("rur_zero_dimensional_failure",)
            )
        witness = tuple(zip(vars_, points[0], strict=True)) if points else None
        return RealAlgebraicFeasibilityResult(
            vars_, bool(points), witness, True, "ars+rur", systems
        )

    systems, complete, notes = _polar_zero_dimensional_systems(
        eqs,
        vars_,
        max_generic_attempts=max_generic_attempts,
        max_pieces=max_pieces,
    )
    for system in systems:
        points, failure = _solve_real_zero_dimensional(system, vars_)
        if failure is not None or points is None:
            return RealAlgebraicFeasibilityResult(
                vars_, None, None, False, "ars", systems, (*notes, "rur_terminal_failure")
            )
        for point in points:
            assignment = dict(zip(vars_, point, strict=True))
            if all(certified_zero(eq.subs(assignment)) is True for eq in eqs):
                witness = tuple((v, sp.simplify(assignment[v])) for v in vars_)
                return RealAlgebraicFeasibilityResult(
                    vars_, True, witness, True, "ars+rur", systems, notes
                )
    if complete:
        return RealAlgebraicFeasibilityResult(vars_, False, None, True, "ars+rur", systems, notes)
    return RealAlgebraicFeasibilityResult(vars_, None, None, False, "ars", systems, notes)


def real_algebraic_feasibility(
    equations: Iterable[sp.Expr | sp.Equality],
    variables: Sequence[sp.Symbol],
    *,
    max_generic_attempts: int = 64,
    max_pieces: int = 128,
    return_result: bool = False,
) -> bool | None | RealAlgebraicFeasibilityResult:
    """Decide real algebraic feasibility.

    Return ``True``, ``False``, or ``None`` (inconclusive) by default. Set
    ``return_result=True`` for witnesses, terminal systems, and diagnostics.
    """

    result = _real_algebraic_feasibility_result(
        equations,
        variables,
        max_generic_attempts=max_generic_attempts,
        max_pieces=max_pieces,
    )
    return result if return_result else result.satisfiable


def real_algebraic_formula_feasibility(
    formula: sp.Expr,
    variables: Sequence[sp.Symbol],
    *,
    max_generic_attempts: int = 64,
    max_pieces: int = 128,
) -> RealAlgebraicFeasibilityResult | None:
    """Try ARS on a conjunction consisting solely of polynomial equalities.

    ``None`` means the formula is outside this specialized fragment. This helper
    is intended for automatic portfolio dispatch before general CAD.
    """

    expr = sp.sympify(formula)
    conjuncts = sp.And.make_args(expr) if isinstance(expr, sp.And) else (expr,)
    equations: list[sp.Expr] = []
    for atom in conjuncts:
        if atom is sp.true or atom == sp.true:
            continue
        if not isinstance(atom, sp.Equality):
            return None
        equations.append(sp.expand(atom.lhs - atom.rhs))
    try:
        return _real_algebraic_feasibility_result(
            equations,
            variables,
            max_generic_attempts=max_generic_attempts,
            max_pieces=max_pieces,
        )
    except (RationalUnivariateError, sp.PolynomialError, ValueError, TypeError):
        return None


def solve_real_algebraic_set(
    equations: Iterable[sp.Expr | sp.Equality],
    variables: Sequence[sp.Symbol],
    **kwargs,
) -> dict[sp.Symbol, sp.Expr] | None:
    """Return one exact real point, ``None`` for certified emptiness, or raise if incomplete."""
    result = real_algebraic_feasibility(equations, variables, return_result=True, **kwargs)
    decision = result.require_decision()
    return result.assignment if decision else None


__all__ = [
    "RealAlgebraicFeasibilityResult",
    "real_algebraic_feasibility",
    "real_algebraic_formula_feasibility",
    "solve_real_algebraic_set",
]
